#include "driver/gpio.h"
#include "esp_adc/adc_oneshot.h"

/* Silkscreen D numbers are not GPIO numbers: D0 is GPIO2. */
gpio_reset_pin(GPIO_NUM_2);
gpio_set_direction(GPIO_NUM_2, GPIO_MODE_OUTPUT);
gpio_set_level(GPIO_NUM_2, 1);

adc_oneshot_unit_handle_t adc1;
adc_oneshot_unit_init_cfg_t unit = { .unit_id = ADC_UNIT_1 };
adc_oneshot_new_unit(&unit, &adc1);

adc_oneshot_chan_cfg_t ch = {
    .atten    = ADC_ATTEN_DB_12,   /* full 0 to ~3.1 V range */
    .bitwidth = ADC_BITWIDTH_DEFAULT,
};
adc_oneshot_config_channel(adc1, ADC_CHANNEL_2, &ch);   /* GPIO2 = D0 */

int raw;
adc_oneshot_read(adc1, ADC_CHANNEL_2, &raw);
